soup_propias = BeautifulSoup(html_propias, "html.parser")
left_table_propias = soup_propias.find("table", class_="Table Table--align-right Table--fixed Table--fixed-left")
teams = []
if left_table_propias:
    tbody_left = left_table_propias.find("tbody")
    if tbody_left:
        for tr in tbody_left.find_all("tr"):
            tds = tr.find_all("td")
            if len(tds) >= 2:
                team_name = tds[1].get_text(strip=True)
                teams.append(team_name)

data_propias = {}
right_table_div_propias = soup_propias.find("div", class_="Table__Scroller")
headers_propias = []
stats_rows_propias = []
if right_table_div_propias:
    right_table = right_table_div_propias.find("table")
    if right_table:
        thead = right_table.find("thead")
        if thead:
            header_tr = thead.find("tr")
            if header_tr:
                for th in header_tr.find_all("th"):
                    headers_propias.append(th.get_text(strip=True))
        tbody_right = right_table.find("tbody")
        if tbody_right:
            for tr in tbody_right.find_all("tr"):
                cells = [td.get_text(strip=True) for td in tr.find_all("td")]
                stats_rows_propias.append(cells)
for idx, team in enumerate(teams):
    if idx < len(stats_rows_propias):
        stats_dict = dict(zip(headers_propias, stats_rows_propias[idx]))
        data_propias[team] = stats_dict

